-- MEMBATALKAN Tahap 3a (2026-11-18-tahap3a-jenis-tambahan.sql).
-- Hanya menghapus jenis tambahan yang BELUM dipakai barang mana pun.

DELETE FROM `types` WHERE `code` IN ('K3-OBAT-NYAMUK-SERANGGA', 'K3-BASKOM-STAINLESS', 'K3-GENTONG-TONG-AIR', 'K3-KEMOCENG', 'K3-RAK-PLASTIK', 'K3-HANGER-JEPIT-JEMURAN', 'K3-TAPLAK-MEJA', 'K3-HIASAN-CERMIN', 'K3-PERKAKAS-KUNCI', 'K3-PISAU', 'K3-SARINGAN-SEROK', 'K3-CETAKAN-LOYANG', 'K3-SOTIL-IRUS-CAPIT', 'K3-TALENAN-PARUTAN-COBEK', 'K3-TEMPAT-BUMBU', 'K3-TEMPAT-SENDOK', 'K3-NAMPAN', 'K3-TUDUNG-SAJI', 'K3-SABUN-KEWANITAAN', 'K3-SISIR', 'K3-SUKU-CADANG-KOMPOR', 'K3-CELANA-DEWASA', 'K3-ATASAN-DEWASA', 'K3-ATRIBUT-SERAGAM')
  AND NOT EXISTS (SELECT 1 FROM `goods` g WHERE g.`type_id` = `types`.`id`);
